<script setup lang="ts">
import { computed, ref } from 'vue'
type Question = { level:number; question:string; options:string[]; answer:number; explanation:string }
const questions:Question[] = [
  {level:1,question:'视频里是熟人本人，声音也很像，对方说手机摔坏了只能用这个新号联系你，并催你立刻转账。第一步最稳妥的做法是什么？',options:['先中断当前联系，再用你自己保存过的号码或其他渠道核实','先转小额试试，对方如果继续要钱再怀疑','让对方再发一段自拍视频，感觉像本人就转','把聊天截图发群里问问大家'],answer:0,explanation:'熟人头像、声音和视频都可以被仿造。涉及金钱时，必须切换到你掌握的独立渠道复核身份。'},
  {level:1,question:'下面哪一项最像 AI 换脸视频的常见破绽？',options:['发言内容过于流利','人物转头时耳朵、下颌线或眼镜边缘出现抖动和模糊','背景很清楚','字幕排版很整齐'],answer:1,explanation:'边缘穿帮、配饰扭曲、轮廓漂移都属于典型视觉异常。'},
  {level:1,question:'有人打电话自称是你领导，声音高度相似，让你立即把验证码报给他完成系统授权。哪种判断最正确？',options:['只要声音像，就先配合领导办事','验证码不算敏感信息，可以口头报','凡是验证码、密码、屏幕共享请求，都必须视为高风险并二次核验','先把验证码发短信，再打电话确认'],answer:2,explanation:'验证码本质上就是授权凭证，不能用声音相似替代组织既有审批链。'},
  {level:1,question:'关于 deepfake，下面哪种理解更准确？',options:['只有全程 AI 生成的视频才算 deepfake','只要是美颜滤镜就算 deepfake','它既可能是从零生成，也可能是在真实素材上做替换、驱动和伪造','只能用于娱乐，不会影响真实决策'],answer:2,explanation:'深度伪造的关键在于误导身份或事实，不局限于从零生成。'},
  {level:2,question:'你看到“知名企业家”推荐投资群，视频自然、评论热闹。最需要优先核验什么？',options:['视频分辨率够不够高','账号和投资项目能否在官方渠道被独立验证','评论区有没有很多点赞','口播用了多少专业术语'],answer:1,explanation:'应核对账号、链接、域名、认证主体和项目资质能否独立成立。'},
  {level:2,question:'下面哪项最能降低“AI 换音 + 熟人诈骗”的成功率？',options:['公开家人的生日和宠物名','提前约定仅内部知道的核验问题或暗号','接到紧急电话时尽量不要挂断','任何熟人来电都默认可信'],answer:1,explanation:'只有真人共享、难以被公开资料猜中的核验信息，才能提高识别能力。'},
  {level:2,question:'下面哪种情况最值得警惕“上下文也被操控”了？',options:['对方要求你只在当前聊天窗口里确认，不要联系其他人','对方能说出你的名字','视频背景是办公室','对方发言语速正常'],answer:0,explanation:'凡是阻止你交叉验证、回拨或走流程，风险都应立即上调。'},
  {level:2,question:'视频里的嘴型、光影、动作都看不出问题，是否就能判定真实？',options:['能，技术细节没问题就说明内容没问题','不能，还取决于来源、发布时间、传播链路和独立佐证','能，只要是大平台发布就都是真的','不能，但只有专业人员才能判断'],answer:1,explanation:'还要核验发布者、原始出处和其他可信证据。'},
  {level:3,question:'单位财务在视频会上收到“领导”指示，要求绕过审批链先付款。最合适的处置是什么？',options:['金额不大就先付','人脸声音都对得上，可以执行','按照既定审批和回拨制度复核','让同事投票决定'],answer:2,explanation:'制度的意义就是在高压和高仿场景下替代个人直觉。'},
  {level:3,question:'哪种素材处理方式最容易引发版权风险？',options:['概括官方文章并附原链接','使用已核对许可的素材','直接搬运完整文章或去水印视频','引用官方视频页并说明来源'],answer:2,explanation:'完整搬运第三方文章和视频最容易踩版权和平台规则。'},
  {level:3,question:'已经把钱转给疑似 AI 仿冒熟人，接下来最优先做什么？',options:['先等对方还钱','继续聊天避免打草惊蛇','尽快联系银行止付、留存证据并报警','删除转账记录'],answer:2,explanation:'第一优先级是止付、留痕、报警。'},
  {level:3,question:'哪句话最能代表成熟的“仿骗意识”？',options:['眼力够好就不会被骗','技术越强越没法防','牵涉身份、金钱、权限就必须做来源和流程双重验证','只防陌生人'],answer:2,explanation:'真正有效的是建立稳定、可重复执行的验证习惯。'},
]
const current = ref(-1), score = ref(0), selected = ref<number|null>(null), done = ref(false)
const question = computed(() => questions[current.value])
const progress = computed(() => done.value ? 100 : Math.max(0,current.value) / questions.length * 100)
const badge = computed(() => score.value >= 12 ? ['深伪侦察官','你已经具备很强的仿骗意识。'] : score.value >= 9 ? ['反诈前哨','你对高压诈骗场景已经有较强判断力。'] : score.value >= 5 ? ['识伪观察员','你能抓到常见换脸换音线索。'] : ['警觉新手','继续把暂停、换渠道、走流程练成习惯。'])
function start(){current.value=0;score.value=0;selected.value=null;done.value=false}
function choose(index:number){if(selected.value!==null)return;selected.value=index;if(index===question.value.answer)score.value++}
function next(){if(current.value===questions.length-1){done.value=true;return}current.value++;selected.value=null}
</script>
<template><section class="quiz-shell"><aside class="quiz-sidebar"><div class="quiz-sidebar__head"><p class="eyebrow">Anti-Scam Drill</p><h1>反诈闯关</h1><p>把“像不像真的”换成“我会不会核验”，用真实诈骗情境练习识别、暂停和复核。</p></div><div class="quiz-sidebar__stats"><div><span>关卡</span><strong>3 级</strong></div><div><span>题量</span><strong>12 题</strong></div><div class="quiz-sidebar__stat quiz-sidebar__stat--title-only"><span>核心能力</span></div></div><div class="quiz-levels"><div class="quiz-levels__item"><span>L1</span><p>基础识别</p></div><div class="quiz-levels__item"><span>L2</span><p>场景判断</p></div><div class="quiz-levels__item"><span>L3</span><p>流程防骗</p></div></div><div class="quiz-sidebar__mission"><span>通关准则</span><strong>涉及转账、验证码、下载软件、屏幕共享时，一律先停下来，再换渠道确认真人身份。</strong><p>重点不是背答案，而是把“暂停、换渠道、走流程”练成默认动作。</p></div><RouterLink class="button button--ghost button--full" to="/education">先看科普频道</RouterLink></aside><div class="quiz-main"><section class="quiz-panel quiz-panel--hero"><div><p class="quiz-panel__eyebrow">Drill Progress</p><h2>每答一题，都会帮你建立一次防骗动作。</h2><p class="quiz-panel__lede">目标不是猜真假，而是在高压场景里依然知道该先做什么。</p></div><div class="quiz-progress"><div class="quiz-progress__bar"><span :style="{width:`${progress}%`}"/></div><div class="quiz-progress__meta"><strong>{{ current < 0 ? '准备开始' : done ? '完成 12 / 12' : `已完成 ${current} / 12` }}</strong><span>{{ done ? '闯关结束' : `L${question?.level || 1}` }}</span></div></div><div class="quiz-stage-strip"><span>先暂停</span><span>再核验</span><span>后处置</span></div></section><section class="quiz-panel quiz-panel--question"><div class="quiz-question-head"><span class="quiz-chip">{{ done ? '已完成' : `第 ${Math.max(1,current+1)} 题` }}</span><span class="quiz-chip">{{ done ? 'RESULT' : `L${question?.level || 1}` }}</span></div><h3>{{ done ? '你的仿骗意识测评已生成。' : question?.question || '点击开始后进入第一题。' }}</h3><div v-if="question && !done" class="quiz-options"><button v-for="(option,i) in question.options" :key="option" class="quiz-option" :class="{'is-correct':selected!==null&&i===question.answer,'is-wrong':selected===i&&i!==question.answer}" :disabled="selected!==null" @click="choose(i)">{{ option }}</button></div><div v-if="selected!==null&&!done" class="quiz-feedback" :class="selected===question.answer?'quiz-feedback--correct':'quiz-feedback--wrong'"><strong>{{ selected===question.answer?'回答正确':'这题答错了' }}</strong><p>{{ question.explanation }}</p></div><div class="quiz-actions"><button v-if="current<0" class="button button--primary" @click="start">开始闯关</button><button v-else-if="selected!==null&&!done" class="button button--secondary" @click="next">{{ current===questions.length-1?'查看结果':'下一题' }}</button><button v-if="done" class="button button--ghost" @click="start">重新挑战</button></div></section><section v-if="done" class="quiz-panel quiz-panel--summary"><p class="quiz-panel__eyebrow">Result</p><h2>{{ badge[0] }}</h2><p>{{ badge[1] }}</p><div class="quiz-summary__grid"><div><span>得分</span><strong>{{ score }} / 12</strong></div><div><span>等级称号</span><strong>{{ badge[0] }}</strong></div><div><span>建议动作</span><strong>把“独立核验身份”变成默认动作</strong></div></div></section></div></section></template>
